int tipc_nl_compat_dump_link(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *tb[TIPC_NL_LINK_ATTR_MAX + 1];
    int err;

    if (!attrs[TIPC_NL_LINK])
        return -EINVAL;

    err = nla_parse_nested(tb, TIPC_NL_LINK_ATTR_MAX, attrs[TIPC_NL_LINK], NULL);
    if (err < 0)
        return err;

    if (!tb[TIPC_NL_LINK_ATTR_DEST] || !tb[TIPC_NL_LINK_ATTR_UP] || !tb[TIPC_NL_LINK_ATTR_NAME])
        return -EINVAL;

    link_attr = nla_nest_start(msg->n, TIPC_NL_COMPAT_LINK);
    if (!link_attr)
        return -EMSGSIZE;

    nla_put_string(msg->n, TIPC_NL_COMPAT_LINK_DEST, nla_get_string(tb[TIPC_NL_LINK_ATTR_DEST]));
    nla_put_flag(msg->n, TIPC_NL_COMPAT_LINK_UP, nla_get_u8(tb[TIPC_NL_LINK_ATTR_UP]));
    nla_put_string(msg->n, TIPC_NL_COMPAT_LINK_NAME, nla_get_string(tb[TIPC_NL_LINK_ATTR_NAME]));

    nla_nest_end(msg->n, link_attr);

    return 0;
}

int tipc_nl_compat_dump_link(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *tb[LINK_ATTR_MAX + 1];
    int err;

    if (!attrs[LINK_ATTR]) {
        return -EINVAL;
    }

    link_attr = attrs[LINK_ATTR];
    err = nla_parse(tb, LINK_ATTR_MAX, nla_data(link_attr), nla_len(link_attr), NULL);
    if (err < 0) {
        return err;
    }

    if (!tb[LINK_DEST]) {
        return -EINVAL;
    }

    if (tb[LINK_STATUS]) {
        msg->status = nla_get_u32(tb[LINK_STATUS]);
    } else {
        msg->status = 0;
    }

    if (tb[LINK_NAME]) {
        strncpy(msg->name, nla_get_string(tb[LINK_NAME]), TIPC_MAX_LINK_NAME);
    } else {
        msg->name[0] = '\0';
    }

    strncpy(msg->dest, nla_get_string(tb[LINK_DEST]), TIPC_MAX_LINK_NAME);

    return 0;
}

