int tipc_dump_link(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *tb[TIPC_NL_LINK_MAX + 1];
    int err;

    if (!attrs[TIPC_NL_LINK])
        return -EINVAL;

    err = nla_parse_nested(tb, TIPC_NL_LINK_MAX, attrs[TIPC_NL_LINK], NULL);
    if (err < 0)
        return err;

    if (!tb[TIPC_NL_LINK_DEST] || !tb[TIPC_NL_LINK_STATUS] ||
        !tb[TIPC_NL_LINK_NAME])
        return -EINVAL;

    err = tipc_nla_add(msg, TIPC_NLA_LINK_DEST, nla_data(tb[TIPC_NL_LINK_DEST]),
                       nla_len(tb[TIPC_NL_LINK_DEST]));
    if (err < 0)
        return err;

    err = tipc_nla_add(msg, TIPC_NLA_LINK_STATUS, nla_data(tb[TIPC_NL_LINK_STATUS]),
                       nla_len(tb[TIPC_NL_LINK_STATUS]));
    if (err < 0)
        return err;

    err = tipc_nla_add(msg, TIPC_NLA_LINK_NAME, nla_data(tb[TIPC_NL_LINK_NAME]),
                       nla_len(tb[TIPC_NL_LINK_NAME]));
    if (err < 0)
        return err;

    return 0;
}

int tipc_nl_compat_dump_link(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *link_info;
    int err;

    if (!attrs[TIPC_NL_COMPAT_ATTR_LINK])
        return -EINVAL;

    link_attr = attrs[TIPC_NL_COMPAT_ATTR_LINK];
    link_info = nla_find(nla_data(link_attr), nla_len(link_attr),
                         TIPC_NL_COMPAT_ATTR_LINK_INFO);

    if (!link_info)
        return -EINVAL;

    msg->type = TIPC_TLV_LINK;
    msg->length = 0;

    err = nla_put_string(msg->nla, TIPC_TLV_LINK_DEST,
                         nla_data(link_info));
    if (err < 0)
        return err;

    err = nla_put_u32(msg->nla, TIPC_TLV_LINK_STATUS,
                      nla_get_u32(link_info + nla_attr_size(link_info)));
    if (err < 0)
        return err;

    err = nla_put_string(msg->nla, TIPC_TLV_LINK_NAME,
                         nla_data(link_info + nla_attr_size(link_info) * 2));
    if (err < 0)
        return err;

    return 0;
}
